}

.node-flow {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.node-flow-chip {
  --chip-color: var(--muted);
  max-width: 100%;
  border: 1px solid color-mix(in srgb, var(--chip-color), transparent 62%);
  border-radius: 999px;
  background: color-mix(in srgb, var(--chip-color), transparent 92%);
