  padding: 5px 7px;
  font-size: 10px;
  font-weight: 800;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.node-flow-chip.tone-good,
.node-metric.tone-good { --chip-color: var(--green); }
.node-flow-chip.tone-warm,
.node-metric.tone-warm { --chip-color: var(--amber); }
.node-flow-chip.tone-active,
.node-metric.tone-active { --chip-color: var(--cyan); }
.node-flow-chip.tone-idle,
.node-metric.tone-idle { --chip-color: var(--blue); }
.node-flow-chip.tone-blocked,
.node-metric.tone-blocked { --chip-color: var(--red); }
.node-flow-chip.tone-off,
.node-metric.tone-off { --chip-color: #66727a; }

.node-metrics {
  display: grid;
  gap: 6px;
}

.node-metric {
  --chip-color: var(--muted);
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 0.78fr) minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  border-left: 3px solid var(--chip-color);
  background: rgba(255,255,255,0.045);
  border-radius: 8px;
  padding: 7px 8px;
}

.node-metric span,
.node-metric strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.node-metric span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.node-metric strong {
  color: var(--text);
  font-size: 12px;
  margin-top: 0;
  text-align: right;
}

.graph-list {
  display: grid;
  gap: 7px;
  margin-top: 9px;
  max-height: 245px;
  overflow: auto;
}

.graph-list-row {
  --row-color: var(--muted);
  display: grid;
  gap: 3px;
  border-left: 3px solid var(--row-color);
  border-radius: 8px;
  background: rgba(255,255,255,0.045);
  padding: 8px 9px;
  min-width: 0;
}

.graph-list-row.tone-good { --row-color: var(--green); }
.graph-list-row.tone-warm { --row-color: var(--amber); }
.graph-list-row.tone-active { --row-color: var(--cyan); }
.graph-list-row.tone-idle { --row-color: var(--blue); }
.graph-list-row.tone-blocked { --row-color: var(--red); }
.graph-list-row.tone-off { --row-color: #66727a; }

.graph-list-row span,
.graph-list-row strong,
.graph-list-row em {
  min-width: 0;
  overflow-wrap: anywhere;
}

.graph-list-row span {
  color: var(--muted);
  font-size: 11px;
}

.graph-list-row strong {
  color: var(--text);
  font-size: 12px;
}

.graph-list-row em {
  color: rgba(145,160,168,0.8);
  font-size: 11px;
  font-style: normal;
}

.graph-list-row.empty {
  color: var(--muted);
  border-left-color: rgba(145,160,168,0.34);
