  padding: 5px 8px;
}

.timeline-head {
  align-content: center;
  padding-right: 8px;
}

.timeline-head strong {
  display: none;
}

.event-timeline {
  align-items: center;
  gap: 0;
  padding-bottom: 0;
}

.timeline-item {
  flex: 0 0 auto;
  min-height: 0;
  max-width: none;
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  padding: 0;
}

.timeline-item:not(:last-child)::after {
  content: "·";
  margin: 0 12px 0 8px;
  color: rgba(145,160,168,0.48);
}

.timeline-item.latest {
  background: transparent;
  box-shadow: none;
}

.timeline-item.latest strong {
  color: color-mix(in srgb, var(--timeline-color), white 34%);
}

.timeline-item span,
.timeline-item strong,
.timeline-item em {
  max-width: none;
  line-height: 1;
}

.timeline-item span {
  color: rgba(145,160,168,0.76);
  font-size: 10px;
}

.timeline-item strong {
  color: rgba(236,244,247,0.9);
  font-size: 11px;
}

.timeline-item em {
  color: rgba(180,193,199,0.78);
  font-size: 10px;
}

@media (min-width: 1181px) {
  .graph-workspace {
    grid-template-columns: minmax(650px, 1fr) minmax(420px, 460px);
  }
}

@media (max-width: 1180px) {
  .graph-workspace {
    grid-template-columns: 1fr;
  }

  .graph-inspector {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .capital-hud,
  .node-inspector {
    grid-column: span 2;
  }
}

@media (max-width: 780px) {
  .graph-inspector {
    grid-template-columns: 1fr;
  }

  .capital-hud,
  .node-inspector {
    grid-column: auto;
  }
}

.graph-node.selected,
.graph-node[data-state="stopped"].selected,
.graph-node[data-state="ready"].selected,
.graph-node[data-state="blocked"].selected {
  opacity: 0.96;
  border-color: color-mix(in srgb, var(--tone-color), white 42%);
  box-shadow:
    inset 3px 0 0 color-mix(in srgb, var(--tone-color), white 10%),
    0 24px 54px rgba(0,0,0,0.5),
    0 0 0 2px color-mix(in srgb, var(--tone-color), transparent 36%),
    0 0 42px color-mix(in srgb, var(--tone-color), transparent 60%);
}

.graph-node.selected::before {
  background: color-mix(in srgb, var(--tone-color), white 14%);
  box-shadow: 0 0 20px color-mix(in srgb, var(--tone-color), transparent 38%);
}

/* ui-review-rules:start */
/* rule: responsive_toolbar */
.ui-review-button {
  white-space: nowrap;
}
.graph-window-controls {
  flex-wrap: wrap;
  row-gap: 6px;
  justify-content: flex-start;
}
.mode-tabs {
  max-width: 100%;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  overflow-x: auto;
  scrollbar-width: none;
}
.mode-tabs::-webkit-scrollbar {
  display: none;
}
.mode-tab {
  flex: 0 0 auto;
  white-space: nowrap;
}
@media (max-width: 720px) {
  .pipeline-status {
    width: 100%;
    justify-content: flex-start;
  }
  .graph-window-controls {
    width: 100%;
  }
  .mode-tabs {
    width: 100%;
    padding: 3px;
  }
  .mode-tab {
    min-height: 30px;
    padding: 6px 8px;
    font-size: 10px;
  }
}

/* rule: long_string_wrap */
.topbar-runtime-summary,
.graph-stat span,
.graph-stat p,
.graph-list-row span,
.graph-list-row em,
.node-flow-chip,
.node-metric span,
.node-metric strong,
.node-micro,
.pipeline-details strong,
.pipeline-details small,
#host-target,
#eno1-owner,
#latest-blocker {
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* rule: meta_contrast */
.graph-stat span,
.graph-stat p,
.topbar-runtime-summary,
.node-micro,
.timeline-item span,
.timeline-item em {
  color: rgba(210, 220, 226, 0.92);
}
.graph-stat span,
.graph-stat p {
  font-size: 12px;
  line-height: 1.45;
}
@media (max-width: 720px) {
  .topbar-runtime-summary,
  .graph-stat span,
  .graph-stat p {
    font-size: 13px;
  }
}

/* rule: card_tone_down */
.graph-inspector .graph-stat {
  box-shadow: none;
  border-color: rgba(255,255,255,0.09);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.025), transparent 64%),
    rgba(6, 10, 12, 0.9);
}
.graph-inspector {
  gap: 12px;
}

/* rule: hierarchy_spacing */
.graph-inspector .graph-stat {
  padding: 16px 18px;
}
.graph-stat strong {
  margin-top: 6px;
  font-size: 15px;
}
.graph-stat small {
  margin-bottom: 2px;
}
@media (max-width: 720px) {
  .graph-inspector .graph-stat {
    padding: 14px 16px;
  }
}

/* rule: timeline_deemphasis */
.timeline-strip {
  min-height: 32px;
  height: 32px;
  padding: 4px 8px;
  opacity: 0.82;
}
.timeline-item {
  gap: 4px;
}
.timeline-item strong {
  font-size: 10px;
}
.timeline-item em {
  font-size: 9px;
}

/* rule: icon_button_alignment */
.graph-icon-button {
  width: 32px;
  height: 32px;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
.graph-icon-button:focus-visible,
.ui-review-button:focus-visible {
  outline: 2px solid rgba(73, 191, 212, 0.68);
  outline-offset: 1px;
}
/* ui-review-rules:end */
